import type { FeaturedDossier } from "./featuredDossiers";
import { secCompanies } from "./secCompanies.generated";
import { sp500Companies } from "./sp500";

type Impact = "BULL CASE" | "BEAR CASE" | "NEUTRAL";
type Profile = {
  ticker: string;
  description: string;
  products: string;
  revenueModel: string;
  edge: string;
  opportunity: string;
  mustGoRight: string;
  thesisBreaker: string;
  drivers: [string, string][];
  risks: [string, string][];
  peers: string[];
  investorUrl: string;
  newsroomUrl: string;
};

const companyByTicker = new Map(sp500Companies.map((company) => [company.ticker, company]));
const secBrowse = (cikOrTicker: string) => `https://www.sec.gov/edgar/browse/?CIK=${encodeURIComponent(cikOrTicker)}&owner=exclude`;
const secForm = (cik: string, form: string) => `https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=${cik}&type=${encodeURIComponent(form)}&owner=exclude&count=40`;
const cleanName = (name: string) => name.replace(/\s*\/[^/]+\/\s*$/i, "").replace(/\s+/g, " ").trim();

function makeDossier(profile: Profile): FeaturedDossier {
  const company = companyByTicker.get(profile.ticker);
  const secCompany = secCompanies[profile.ticker];
  if (!company || !secCompany) throw new Error(`Missing company or SEC identity for ${profile.ticker}`);
  const name = company.name.replace(/\s+CLASS [A-Z]$/i, "").replace(/\s+INC$/i, " Inc.").replace(/\s+CORP$/i, " Corp.");
  const driverImpacts: Impact[] = ["BULL CASE", "NEUTRAL", "BEAR CASE"];

  return {
    ticker: profile.ticker,
    reviewed: "August 2, 2026",
    completeness: 100,
    newsroomUrl: profile.newsroomUrl,
    description: profile.description,
    lede: `${name} earns owner value through ${profile.revenueModel.toLowerCase()} The three questions that matter most are ${profile.drivers.slice(0, 3).map((driver) => driver[1].toLowerCase()).join(", ")}.`,
    sells: profile.products,
    revenueModel: profile.revenueModel,
    opportunity: profile.opportunity,
    mustGoRight: profile.mustGoRight,
    editorNote: `Treat the claimed advantage—${profile.edge.toLowerCase()}—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.`,
    bullTitle: "What can compound owner value",
    bull: [
      profile.edge,
      profile.opportunity,
      `Visible progress in ${profile.drivers[0][0].toLowerCase()} and ${profile.drivers[1][0].toLowerCase()} can improve the durability and quality of earnings.`,
      "Disciplined reinvestment and capital allocation can convert operating progress into per-share value.",
    ],
    bearTitle: "What can impair the thesis",
    bear: profile.risks.map(([title, signal]) => `${title} can weaken the owner outcome; monitor ${signal.toLowerCase()}.`).concat("A valuation that assumes flawless execution can fall even when the underlying business remains viable."),
    thesisBreaker: profile.thesisBreaker,
    financialDrivers: [
      ...profile.drivers.map(([label, detail]) => ({ label, value: "Primary owner KPI", detail })),
      { label: "BALANCE SHEET", value: "Capacity and resilience", detail: "Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure." },
      { label: "CASH CONVERSION", value: "Earnings quality", detail: "Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow." },
      { label: "PER-SHARE VALUE", value: "Owner conversion", detail: "Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital." },
    ],
    risks: [
      ...profile.risks.map(([title, signal]) => ({ title, level: "High" as const, text: `${title} can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.`, signal })),
      { title: "Capital allocation", level: "Medium", text: "Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.", signal: "Return on invested capital, leverage, share count, impairment charges, and post-deal performance" },
      { title: "Legal, regulatory, and reporting", level: "Medium", text: "Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.", signal: "Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language" },
    ],
    monitor: [
      ...profile.drivers.slice(0, 3).map(([label, detail], index) => ({ title: label, text: `Track ${detail.toLowerCase()} and compare each update with management's prior commitments.`, impact: driverImpacts[index] })),
      { title: "Quarterly thesis audit", text: "Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.", impact: "NEUTRAL" },
    ],
    questions: [
      `Which disclosed measure most reliably verifies ${profile.drivers[0][0].toLowerCase()}?`,
      `What would cause ${profile.drivers[1][0].toLowerCase()} to structurally improve or deteriorate?`,
      `How should owners separate cyclical movement from durable change in ${profile.drivers[2][0].toLowerCase()}?`,
      `Where does ${name} have the greatest unpriced customer, supplier, or regulatory dependency?`,
      "Which management commitment is most important to verify in the next two reporting periods?",
      "What measurable development would invalidate the owner thesis rather than merely create short-term volatility?",
    ],
    competitors: profile.peers.map((ticker) => cleanName(secCompanies[ticker]?.name ?? ticker)).join(", "),
    comparables: profile.peers.map((ticker) => ({
      name: cleanName(secCompanies[ticker]?.name ?? ticker),
      ticker,
      ownership: "Public" as const,
      relationship: `Operating and valuation reference for ${profile.ticker}`,
      valuation: "Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.",
      financialStatus: `Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ${profile.ticker}.`,
      sourceUrl: secBrowse(secCompanies[ticker]?.cik ?? ticker),
    })),
    sources: [
      { title: `${profile.ticker} SEC filing library`, meta: "SEC EDGAR · Exact filer", href: secBrowse(secCompany.cik), excerpt: `${cleanName(secCompany.name)} filings provide the audited financial record, business description, material risks, commitments, governance, and current reports.` },
      { title: `${profile.ticker} annual reports`, meta: "SEC Forms 10-K · Primary filings", href: secForm(secCompany.cik, "10-K"), excerpt: "Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks." },
      { title: `${profile.ticker} quarterly reports`, meta: "SEC Forms 10-Q · Primary filings", href: secForm(secCompany.cik, "10-Q"), excerpt: "Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion." },
      { title: `${profile.ticker} proxy statements`, meta: "SEC DEF 14A · Governance source", href: secForm(secCompany.cik, "DEF 14A"), excerpt: "Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals." },
      { title: `${profile.ticker} investor relations`, meta: "Company primary materials", href: profile.investorUrl, excerpt: "Official earnings releases, presentations, events, governance materials, and shareholder information published by the company." },
      { title: `${profile.ticker} official newsroom`, meta: "Company announcements", href: profile.newsroomUrl, excerpt: "Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification." },
    ],
  };
}

